layers.vertex:
attribute vec3 aO; attribute float aT, aK; attribute vec4 aD; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){ float u = uTime - aT; if (u < 0. || u > 1.00){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK; vP = position.xy;
      if (aK > 2.5){                                          // Weave: a resource mote flies back to the caster on a curved path
        float k = clamp((u - aD.w)/.45, 0., 1.); if (u < aD.w || k >= 1.){ gl_Position = vec4(2.,2.,2.,1.); return; }
        float e = k*k*(3. - 2.*k); vec3 A = aO + vec3(0., 1.2, 0.), B = aD.xyz;
        vec3 side = normalize(cross(B - A, vec3(0., 1., 0.)))*sin(aD.w*37.)*.8;
        vec3 P = mix(A, B, e) + (side + vec3(0., .9, 0.))*sin(3.14159*e);
        vec4 mv = viewMatrix*vec4(P, 1.); float S = .09; mv.xy += position.xy*S; vU = k; gl_Position = projectionMatrix*mv; return; }
      if (aK < .5){ float S = .95; vP = position.xy*S; gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.); }
      else if (aK < 1.5){ vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.25, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.32; mv.xy += position.xy*vec2(.26, .3); gl_Position = projectionMatrix*mv; }
      else { vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.25, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.75;   /* well in front of the chest: the body never cuts the quad */ float S = .8; mv.xy += position.xy*S; vP = position.xy*S; gl_Position = projectionMatrix*mv; }
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU, vK; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float h1(float n){ return fract(sin(n*91.7)*43758.5); }
    void main(){
      float lum = 0., hot = 0., t = vU/1.00;
      if (vK < .5){
        float r = length(vP), e = pow(clamp(vU/.25, 0., 1.), 3.), R = .8 - .65*e, f = (vU < .033 ? 1.5 : 1.)*(1. - smoothstep(.55, 1., t));
        lum += exp(-pow(abs(r - R)/.016, 2.4))*f; hot += lcore(r - R, .005)*f*.6;
        lum *= smoothstep(.95, .85, r); hot *= smoothstep(.95, .85, r);
      } else if (vK < 1.5){
        // Manifest · Burn mark: a small flame sigil held on the target after the impact (brief, then the status cue takes over)
        float x = vP.x, y = vP.y*.5 + .5, t = clamp((vU - .2)/.6, 0., 1.);
        vec2 q = vec2(x*2.2, (y - .55)*4.6); float r = length(q);
        float flame = smoothstep(.55, .45, length(vec2(q.x*(1.3 + q.y*.5), q.y + .2)))*smoothstep(-.9, -.4, q.y)*(1. - smoothstep(.55, 1.1, q.y + .1*sin(vU*30.)));
        float edge = flame*(1. - smoothstep(.3, .45, length(vec2(q.x*(1.3 + q.y*.5), q.y + .2))));
        float f = step(.2, vU)*(vU < .233 ? 1.8 : 1.)*(1. - smoothstep(.55, 1., t));
        lum += (flame - edge*.7)*f*1.1; hot = edge*f*.2;
        lum *= smoothstep(1., .75, abs(x)); hot *= smoothstep(1., .75, abs(x));
      } else {
        if (vK > 2.5){ float r = length(vP); float m = exp(-r*r*8.)*(1. - vU)*1.6;       // Weave mote
          vec3 o = uGold*m + vec3(1., .95, .8)*exp(-r*r*40.)*(1. - vU);
          if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 0.); return; }
        /* Combust (icon), physical fire: a hot core swells inside the chest, then bursts into flame tongues that cool
           from yellow to red to smoke as they travel out (premultiplied: hot adds light, smoke darkens) - no ring, no mark */
        float r = length(vP), a = atan(vP.y, vP.x), b = vU - 0.30;
        float h1 = fract(sin(dot(floor(vP*9.), vec2(127.1, 311.7)))*43758.5);
        vec2 pn = vP*6. - vP/max(r, .05)*max(b, 0.)*5. + vec2(3.7, 1.3);   /* cartesian noise pushed outward: no pole at the centre */
        vec2 ip = floor(pn), fp = fract(pn); fp = fp*fp*(3. - 2.*fp);
        #define HH(q) fract(sin(dot(q, vec2(127.1, 311.7)))*43758.5)
        float n = mix(mix(HH(ip), HH(ip + vec2(1., 0.)), fp.x), mix(HH(ip + vec2(0., 1.)), HH(ip + vec2(1., 1.)), fp.x), fp.y);
        float dens, T;
        if (b < 0.){ float k = vU/0.30;                                     /* build-up: a small core glows through */
          dens = exp(-r*r*(90. - 60.*k*k))*(.4 + .6*k); T = .55 + .45*k;
        } else {
          float t = clamp(b/.6, 0., 1.), e = 1. - pow(1. - clamp(b/.15, 0., 1.), 3.);
          float rays = 0.;
          for (int i = 0; i < 14; i++){ float fi = float(i), hh = fract(sin(fi*71.3)*4375.5);
            float ac = fi*.4488 + (hh - .5)*.35, r0 = .12 + .08*fract(hh*7.3), L = (.28 + .3*hh)*e;   /* each tongue starts at its own radius, not all at the centre */                      /* 14 short tongues of irregular length */
            float aw = a - ac + .9*(r - .2)*(hh - .5);   /* tongues bend a little: gaps never point at the centre */
            float d = sin(aw)*r, along = cos(aw)*r - r0;
            float w = (.03 + .07*(1. - along/max(L, .01)))*step(0., along);
            rays += exp(-pow((d - .04*sin(along*12. - b*20. + fi)*along)/w, 2.))*smoothstep(L, L*.3, along)*smoothstep(0., .1, along); }
          rays *= smoothstep(.1, .26, r);                                                 /* no pinch point where the tongues would meet */
          dens = (min(rays, 1.)*(.55 + .6*n) + exp(-r*r*14.)*(.55 + .7*n)*(1. - t*.8))*(1. - t*t);   /* a soft, noisy fire ball fills the middle */
          T = clamp((1. - r/.6)*(1. - t*.9)*(.7 + .5*n), 0., 1.);                          /* hottest at the centre, cools outward and over time */
        }
        dens *= smoothstep(.75, .55, r);
        vec3 smoke = vec3(.03, .02, .015), red = vec3(.45, .05, .01), org = vec3(.95, .33, .04), yel = vec3(1., .75, .35);
        vec3 col = T < .3 ? mix(smoke, red, T/.3) : (T < .7 ? mix(red, org, (T - .3)/.4) : mix(org, yel, (T - .7)/.3));
        vec3 c = col*dens*(.15 + 1.1*T*T);
        float al = dens*(1. - T)*(1. - T)*.18;   /* only a faint smoke veil: a strong one darkens the fog around the target and reveals its silhouette */
        if (!(max(c.r, max(c.g, max(c.b, al))) >= .002)) discard; gl_FragColor = vec4(c, al); return;
      }
      vec3 o = uOrange*lum + mix(uGold, vec3(1.), .5)*hot;
      if (max(o.r, max(o.g, o.b)) < .002) discard;
      gl_FragColor = vec4(o, 0.);
    }
